-- Reproducible Move employee RLS rules. Run after move_initial and move_membership_self_read.
-- This migration has been applied to styhag_db. Never grant anon access.
create policy move_job_assigned_read on move.jobs for select to authenticated using (exists(select 1 from move.job_assignments a join move.memberships m on m.id=a.employee_id and m.organization_id=a.organization_id where a.job_id=jobs.id and a.organization_id=jobs.organization_id and m.user_id=(select auth.uid())));
create policy move_assignment_self_read on move.job_assignments for select to authenticated using (exists(select 1 from move.memberships m where m.id=job_assignments.employee_id and m.organization_id=job_assignments.organization_id and m.user_id=(select auth.uid())));
create policy move_availability_self_read on move.employee_availability for select to authenticated using (exists(select 1 from move.memberships m where m.id=employee_availability.employee_id and m.organization_id=employee_availability.organization_id and m.user_id=(select auth.uid())));
create policy move_availability_self_insert on move.employee_availability for insert to authenticated with check (exists(select 1 from move.memberships m where m.id=employee_availability.employee_id and m.organization_id=employee_availability.organization_id and m.user_id=(select auth.uid())));
create policy move_availability_self_update on move.employee_availability for update to authenticated using (exists(select 1 from move.memberships m where m.id=employee_availability.employee_id and m.organization_id=employee_availability.organization_id and m.user_id=(select auth.uid()))) with check (exists(select 1 from move.memberships m where m.id=employee_availability.employee_id and m.organization_id=employee_availability.organization_id and m.user_id=(select auth.uid())));
create policy move_availability_self_delete on move.employee_availability for delete to authenticated using (exists(select 1 from move.memberships m where m.id=employee_availability.employee_id and m.organization_id=employee_availability.organization_id and m.user_id=(select auth.uid())));
create policy move_time_self_read on move.time_entries for select to authenticated using (exists(select 1 from move.memberships m where m.id=time_entries.employee_id and m.organization_id=time_entries.organization_id and m.user_id=(select auth.uid())));
create policy move_time_self_insert on move.time_entries for insert to authenticated with check (status in ('draft','submitted') and approved_by is null and approved_at is null and exists(select 1 from move.memberships m where m.id=time_entries.employee_id and m.organization_id=time_entries.organization_id and m.user_id=(select auth.uid())));
create policy move_offer_self_read on move.shift_offers for select to authenticated using (exists(select 1 from move.memberships m where m.id=shift_offers.employee_id and m.organization_id=shift_offers.organization_id and m.user_id=(select auth.uid())));
grant select on move.jobs,move.job_assignments,move.employee_availability,move.time_entries,move.shift_offers to authenticated;
grant insert,update,delete on move.employee_availability to authenticated;
grant insert on move.time_entries to authenticated;
